const crypto = require('crypto');
const secret = $env.N8N_HMAC_SECRET || 'travelai_n8n_hmac_dev_secret_change_me';
const body = $json.body || $json;
const raw = typeof $json.body === 'string' ? $json.body : JSON.stringify(body);
const sig = ($json.headers && ($json.headers['x-signature-sha256'] || $json.headers['X-Signature-SHA256'])) || '';
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (!sig || sig !== expected) {
  throw new Error('Invalid HMAC signature');
}
const destination = body.destination || 'Việt Nam';
const daysCount = Math.min(Math.max(Number(body.days) || 3, 1), 21);
const budget = Number(body.budgetVnd) || 5000000;
const style = body.style || 'couple';
const hotelHints = Array.isArray(body.hotelHints) ? body.hotelHints : [];
const days = [];
for (let i = 1; i <= daysCount; i++) {
  days.push({
    day: i,
    title: `Ngày ${i} · ${destination}`,
    activities: [
      { time: '08:30', title: 'Ăn sáng & khởi động', description: `Phong cách ${style}: chọn quán địa phương gần khách sạn.`, place: destination },
      { time: '10:00', title: i === 1 ? 'Điểm biểu tượng' : 'Trải nghiệm chính', description: 'Đặt vé trước nếu cuối tuần; mang nước và kem chống nắng.', place: destination },
      { time: '15:00', title: 'Văn hóa / thiên nhiên', description: 'Nhịp vừa phải, ưu tiên an toàn và trải nghiệm xác thực.', place: destination },
      { time: '19:00', title: 'Ẩm thực tối', description: 'Thử đặc sản vùng miền; giữ hoá đơn nếu cần claim.', place: destination }
    ]
  });
}
return [{
  json: {
    destination,
    days,
    estimatedBudgetVnd: budget,
    hotelSuggestions: hotelHints,
    transportTips: ['Bay nội địa nếu quãng đường dài', 'Grab/xe ôm công nghệ trong thành phố'],
    foodTips: ['Ăn sáng địa phương', 'Uống nước đóng chai khi di chuyển'],
    degraded: false
  }
}];
